func TestImportSCAConfidenceAndVerdicts(t *testing.T) {
	parse := func(file, format string) []Finding {
		t.Helper()
		raw, err := os.ReadFile("testdata/imports/" + file)
		if err != nil {
			t.Fatal(err)
		}
		fs, err := ParseImport("import-sca-x", format, raw)
		if err != nil {
			t.Fatal(err)
		}
		return fs
	}
	// govulncheck: the deepest level of each vulnerability, with its
	// reachability in the description.
	g := parse("govulncheck.json", "govulncheck")
	byRule := map[string]Finding{}
	for _, f := range g {
		byRule[f.RuleID] = f
	}
	called, imported, required := byRule["GO-2022-1059"], byRule["GO-2023-1988"], byRule["GO-2022-0969"]
	if called.Confidence != "high" || !strings.Contains(called.Description, "Reachability: called") ||
		!strings.Contains(called.Description, "golang.org/x/text/language.ParseAcceptLanguage") || !strings.Contains(called.Description, "main.go:12") {
		t.Errorf("called: %+v", called)
	}
	if imported.Confidence != "low" || !strings.Contains(imported.Description, "imported, not called") || !strings.Contains(imported.Description, "golang.org/x/net/html") {
		t.Errorf("imported: %+v", imported)
	}
	if required.Confidence != "low" || !strings.Contains(required.Description, "required, not imported") {
		t.Errorf("required: %+v", required)
	}
	// Verdicts of the source tool lower the confidence; nothing is dropped
	// except Dependabot alerts that are fixed.
	for _, c := range []struct {
		file, format string
		i            int
	}{{"dependabot.json", "dependabot", 1}, {"dependency-track.json", "dependency-track", 1}, {"mend-platform.json", "mend", 1},
		{"blackduck.json", "blackduck", 1}, {"blackduck-security.csv", "blackduck", 1}, {"nexus-iq.json", "nexus-iq", 1},
		{"nexus-iq-policy.json", "nexus-iq", 1}, {"dep-scan.json", "dep-scan", 1}} {
		fs := parse(c.file, c.format)
		if fs[c.i].Confidence != "low" || fs[0].Confidence == "low" {
			t.Errorf("%s: confidence %q / %q", c.file, fs[0].Confidence, fs[c.i].Confidence)
		}
	}
	if d := parse("dependabot.json", "dependabot"); !strings.Contains(d[1].Description, "tolerable_risk") {
		t.Errorf("dismissal reason: %s", d[1].Description)
	}
	// No severity in the source: medium, and the description says so.
	for _, c := range []struct{ file, format string }{{"safety-v2.json", "safety"}, {"composer-audit.json", "composer-audit"}, {"cargo-audit.json", "cargo-audit"}} {
		for _, f := range parse(c.file, c.format) {
			if strings.Contains(f.Description, "imported as medium") && f.Severity != "medium" {
				t.Errorf("%s: %+v", c.file, f)
			}
		}
	}
	if c := parse("composer-audit.json", "composer-audit")[2]; !strings.Contains(c.Description, "no severity") {
		t.Errorf("composer null severity: %+v", c)
	}
	if b := parse("bundler-audit.json", "bundler-audit"); b[0].CVSS == nil || *b[0].CVSS != 7.5 {
		t.Errorf("bundler-audit cvss: %+v", b[0])
	}
}

func TestImportSCAYarnRepeatsAreOneFinding(t *testing.T) {
	line := func(path string) string {
		return `{"type":"auditAdvisory","data":{"resolution":{"id":1,"path":"` + path + `","dev":false},"advisory":{"id":1,"module_name":"minimist","severity":"high","cves":["CVE-2021-44906"],"cwe":"CWE-1321","github_advisory_id":"GHSA-xvch-5gv4-984h","patched_versions":">=1.2.6","vulnerable_versions":"<1.2.6","title":"Prototype Pollution","overview":"x","url":"https://github.com/advisories/GHSA-xvch-5gv4-984h","findings":[{"version":"1.2.5","paths":["a>minimist","b>minimist"]}]}}}`
	}
	doc := `{"type":"info","data":"x"}` + "\n" + line("a>minimist") + "\n" + line("b>minimist") + "\n" + `{"type":"auditSummary","data":{"vulnerabilities":{"high":2}}}` + "\n"
	fs, err := ParseImport("import-sca-x", "", []byte(doc))
	if err != nil || len(fs) != 1 || !strings.Contains(fs[0].Description, "a>minimist") || !strings.Contains(fs[0].Description, "b>minimist") {
		t.Fatalf("%v %+v", err, fs)
	}
}

func TestImportSCADetection(t *testing.T) {
	// Empty reports with the tool's envelope are detected and give no
	// findings.
	for doc, f := range map[string]string{
		`{"version":"5.7.0","start":"2026-01-01T00:00:00Z","data":[],"messages":[],"errors":[],"time":0.1}`:                                   "retire-js",
		`{"type":"auditSummary","data":{"vulnerabilities":{},"dependencies":3}}`:                                                              "yarn-audit",
		`{"actions":[],"advisories":{},"muted":[],"metadata":{"vulnerabilities":{}}}`:                                                         "pnpm-audit",
		`{"advisories":[],"abandoned":[]}`:                                                                                                    "composer-audit",
		`{"database":{},"lockfile":{"dependency-count":3},"settings":{},"vulnerabilities":{"found":false,"count":0,"list":[]},"warnings":{}}`: "cargo-audit",
		`{"version":"0.9.3","created_at":"2026-01-01 00:00:00 +0000","results":[]}`:                                                           "bundler-audit",
		`{"config":{"protocol_version":"v1.0.0","scanner_name":"govulncheck"}}`:                                                               "govulncheck",
		`{"report_meta":{"json_version":1},"scanned_packages":{},"vulnerabilities":[]}`:                                                       "safety",
		`{"version":1,"parameters":"--vulnerable","projects":[]}`:                                                                             "dotnet-vulnerable",
		`{"version":"1.2","meta":{"application":"Dependency-Track"},"project":{},"findings":[]}`:                                              "dependency-track",
		`{"total_rows":0,"rows":[]}`: "jfrog-xray",
	} {
		if got := DetectImportFormat([]byte(doc)); got != f {
			t.Errorf("%s: detected %q, want %q", doc, got, f)
		}
		if fs, err := ParseImport("import-sca-x", f, []byte(doc)); err != nil || len(fs) != 0 {
			t.Errorf("%s: %v %d", f, err, len(fs))
		}
	}
	// npm 6 reports (with runId) stay npm audit; PATHOS findings JSON stays
	// pathos.
	for doc, f := range map[string]string{
		`{"actions":[],"advisories":{},"muted":[],"metadata":{},"runId":"x"}`: "npm-audit",
		`{"tool":"x","findings":[]}`:                                          "pathos",
		`{"meta":{"application":"other"},"project":{},"findings":[]}`:         "",
	} {
		if got := DetectImportFormat([]byte(doc)); got != f {
			t.Errorf("%s: detected %q, want %q", doc, got, f)
		}
	}
	// A CycloneDX document with vulnerabilities from another tool is not
	// a dep-scan report.
	if got := DetectImportFormat([]byte(`{"bomFormat":"CycloneDX","metadata":{"tools":{"components":[{"name":"trivy"}]}},"vulnerabilities":[]}`)); got == "dep-scan" {
		t.Error("CycloneDX from another tool detected as dep-scan")
	}
	// Malformed records are errors, not silently skipped.
	for f, doc := range map[string]string{
		"retire-js":         `{"data":[{"file":"a.js","results":[{"version":"1"}]}],"start":"x"}`,
		"dependabot":        `[{"number":1,"state":"open","dependency":{},"security_advisory":{}}]`,
		"dependency-track":  `{"meta":{"application":"Dependency-Track"},"project":{},"findings":[{"component":{"name":"x"},"vulnerability":{}}]}`,
		"mend":              `{"vulnerabilities":[{"name":"CVE-2020-1","library":{}}]}`,
		"blackduck":         `{"items":[{"componentName":"x","vulnerabilityWithRemediation":{}}]}`,
		"jfrog-xray":        `{"rows":[{"issue_id":"XRAY-1"}]}`,
		"nexus-iq":          `{"components":[{"componentIdentifier":{"coordinates":{}},"securityData":{"securityIssues":[]}}]}`,
		"safety":            `{"report_meta":{},"scanned_packages":{},"vulnerabilities":[{"package_name":"x"}]}`,
		"composer-audit":    `{"advisories":{"a/b":[{"title":"x"}]},"abandoned":[]}`,
		"cargo-audit":       `{"database":{},"lockfile":{},"vulnerabilities":{"list":[{"advisory":{"id":"RUSTSEC-1"}}]},"warnings":{}}`,
		"bundler-audit":     `{"version":"1","created_at":"x","results":[{"type":"unpatched_gem","gem":{"name":"rack"},"advisory":{}}]}`,
		"dotnet-vulnerable": `{"version":1,"projects":[{"path":"a.csproj","frameworks":[{"topLevelPackages":[{"id":"X","vulnerabilities":[{"severity":"High"}]}]}]}]}`,
		"govulncheck":       `{"config":{"scanner_name":"govulncheck"}}` + "\n" + `{"finding":{"osv":"GO-1"}}`,
		"yarn-audit":        `{"type":"auditAdvisory","data":{"advisory":{}}}`,
	} {
		if _, err := ParseImport("import-sca-x", f, []byte(doc)); err == nil {
			t.Errorf("%s: malformed record accepted", f)
		}
	}
}
